const crypto = require('crypto');

const apiKey = $input.all()[0].json.api_key;
const apiSecret = $input.all()[0].json.secret;
const timestamp = String($input.all()[0].json.timestamp);

const hash = crypto.createHmac('sha1', apiSecret)
  .update(apiKey + timestamp)
  .digest('hex');

return [{
  json: {
    api_key: apiKey,
    timestamp: timestamp,
    hash: hash
  }
}];

// convert string parameters to valid json object
const nodeData = $('FreedCamp Get Request').all()[0].json.params;
const paramString = typeof nodeData === 'string' ? JSON.parse(nodeData) : nodeData;
return [{ json: paramString }];

const rawParams = $('FreedCamp Get Request').all()[0].json.params;
const data = typeof rawParams === 'string' ? JSON.parse(rawParams) : rawParams;
const params = [];
for (const [key, value] of Object.entries(data)) {
  if (Array.isArray(value)) {
    const keyName = key.endsWith('[]') ? key : `${key}[]`;
    for (const item of value) {
      params.push(`${encodeURIComponent(String(keyName))}=${encodeURIComponent(String(item))}`);
    }
  } else {
    params.push(`${encodeURIComponent(String(key))}=${encodeURIComponent(String(value))}`);
  }
}
const urlParams = params.join('&');
return [{ json: { url_params: urlParams } }];

// filter for required outputs with dot notation
function getValueByPath(obj, path, keepArrays = true) {
  try {
    const parts = path.split('.');
    const current = obj;
    if (current[parts[0]] === undefined || current[parts[0]] === null) return null;
    if (parts.length === 1) return current[parts[0]];
    const firstPart = parts[0];
    const restPath = parts.slice(1).join('.');
    const firstValue = current[firstPart];
    if (Array.isArray(firstValue)) {
      if (keepArrays) {
        const results = [];
        for (const item of firstValue) {
          const itemValue = getValueByPath(item, restPath, keepArrays);
          if (itemValue !== null) results.push(itemValue);
        }
        return results.length > 0 ? results : null;
      } else {
        const results = [];
        for (const item of firstValue) {
          const itemValue = getValueByPath(item, restPath, keepArrays);
          if (itemValue !== null) results.push(String(itemValue));
        }
        return results.length > 0 ? results.join(' | ') : null;
      }
    }
    return getValueByPath(firstValue, restPath, keepArrays);
  } catch (e) { return null; }
}

try {
  const inputData = $('If sucessful').all()[0].json;
  let requiredFields = $('FreedCamp Get Request').all()[0].json.required_outputs;
  if (typeof requiredFields === 'string') requiredFields = JSON.parse(requiredFields);
  const dataObj = inputData.data;
  let tasks = dataObj.tasks || dataObj.projects || dataObj.users || dataObj.comments;
  if (!tasks || !Array.isArray(tasks) || tasks.length === 0) {
    return [{ json: { error: 'No tasks/projects/users found' } }];
  }
  const results = [];
  for (const task of tasks) {
    const result = {};
    for (const field of requiredFields) {
      const value = getValueByPath(task, field, true);
      const parentPathValue = getValueByPath(dataObj, field, true);
      if (value !== null) result[field] = value;
      else if (parentPathValue !== null) result[field] = parentPathValue;
    }
    if (Object.keys(result).length > 0) results.push({ json: result });
  }
  if (results.length === 0) return [{ json: { error: 'No matching data found for the required fields' } }];
  return results;
} catch (e) {
  return [{ json: { error: `Processing error: ${e.message}` } }];
}
